// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c) && amount > 0 && amount < type(uint256).max / 2);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        bool ok1;
        vm.prank(actor);
        try c.withdraw(amount) { ok1 = true; } catch { ok1 = false; }
        bool ok2;
        vm.prank(actor);
        try c.withdraw(amount) { ok2 = true; } catch { ok2 = false; }
        assertTrue(ok1 && !ok2 && address(c).balance == 0, "withdrawing the full balance twice must fail on the second attempt");
    }
}
